insert into public.app_config(key, value) values ('rules_text', $cfg$"- Use font size 9 throughout the CV\n- Use Calibri font only\n- All headings and sub-headings must be bold\n- Email ID and LinkedIn (full URL) must be clickable blue hyperlinks; add portfolio link (full URL, hyperlinked) if applicable\n- Headings on the left, left-aligned; dates and locations in the right column, left-aligned\n- Use gridlines/tables for layout stability (strict)\n- Name in CAPS, bold, black. Educational institutions and company names all in the same CAPS format\n- Underline sub-skill headings inside experience/internships; italicise company descriptions/roles in brackets on one line next to the main header\n- Submit only in PDF format\n- Bullet points should ideally fill one full line (no spill-over to a second line, no half-empty lines)\n- Italics for Professional Summary and company descriptions\n- Use bar marks ( | ) as separators, not full stops\n- No grammar or spelling mistakes\n- Whole resume must fit on exactly one A4 page\nHEADER:\n- Name, phone number, email ID and LinkedIn profile (full URL); portfolio full URL if any\n- At the top of the resume, centred\nPROFESSIONAL SUMMARY:\n- 50-60 words; 3-4 lines max\n- Do not start with 'I'; start with an action verb; focus on measurable achievements and outcomes\n- Highlight spikes: leadership, awards, entrepreneurship, sports or expertise\n- Create a clear professional identity aligned to the target domain\n- Concise, recruiter-friendly language\nEDUCATION:\n- Reverse chronological order\n- Institution names in CAPS, spelled exactly as the institution writes its name\n- Programme written in full form (e.g. 'MBA in Finance'), not as a bare abbreviation\n- Degree, institution and graduation year clearly stated\n- Bar marks instead of full stops; write CBSE Class X & XII in Roman numerals\n- Mention CGPA/percentage only if above 80% (8.0/10)\n- Year format '2026-Present', latest first\nEXPERIENCE:\n- Clearly mention title/designation, company, duration\n- Bullets follow Result-Action-Context (RAC): lead with the result, then the action, then the context\n- Include measurable outcomes and impact (numbers, %, ₹, scale)\n- Remove experiences irrelevant to the target domain\n- Bullets easy to understand and outcome-oriented\n- Date range in month'yy format, e.g. Apr'24-Jul'24\n- Group bullets under underlined bold-italic sub-skill headings (e.g. 'Growth Marketing & Revenue Impact') when a role has 4+ bullets\nPROJECTS:\n- Project name, date and role\n- Clearly explain actions taken\n- Mention measurable results and impact\n- Focus on research, live projects, freelance work or college contributions\n- Date range in month'yy format\nEXTRACURRICULAR LEADERSHIP AWARDS CERTIFICATIONS:\n- Mention positions of responsibility and ownership\n- Include measurable achievements: footfall, revenue, sponsorship, participants, timeframe\n- Only credible and relevant certifications\n- Add competition scale or ranking context (e.g. 1st of 150, national level)\n- Dates optional, format Jul'24\nSKILLS:\n- Only relevant business and technical skills\n- Every skill must be backed by experience/projects in the resume\n- Align skills with the target role/domain keyword list\n- Group skills logically into buckets (Business Skills | Technical Skills)\n- Concise and scannable"$cfg$::jsonb)
  on conflict (key) do update set value = excluded.value, updated_at = now();
insert into public.app_config(key, value) values ('master_guidelines', $cfg$"academic achievements: Cover: position out of total (top 10%ile, 10/350), year, quantified scholarship/prize money/funds. Types: scholarships (purpose, amount, out of how many, awarded by, when), institute/department rank & medals, olympiads (conducted by, subject, state/national/international rank, year), competitive exams (CAT/GMAT/GRE/JEE/XAT score, admits, year), professional courses (CFA, CS, Six Sigma, NCFM), job/PPO offers, recommendations, academic projects (papers, dissertations, academic internships), online courses (score, sponsorship).\ncertifications: Full name, issuing organisation, year; level/tier (e.g. CFA Level 1, Six Sigma Green Belt); score/percentile/distinction; selection criteria or rank; sponsorship; projects done, tools learned, real-world application.\nwork experience: Position | Company | Tenure. Achievements covering: impact & business results; core responsibilities & skill development; innovation & process enhancements; stakeholder management & collaboration; professional recognition & endorsements. Record everything: trainings, ideas proposed, projects, tools, people mentored.\ninternships: Position | Company | Tenure. Recognition & key takeaways; key contributions & learnings; process improvements/new ideas; client/team exposure; LOR/LOA from seniors.\nb plan: B-plan competition position/award and outcome; venture idea, seed funding, outcome; national-level case competitions.\npositions of responsibility: Heads: student council, cultural/tech/management fest, NGO, clubs/committees (literary, theatre, E-cell, NEN, sports), team/house captain, class rep, workplace leadership (thread lead, CSR). Roles: treasurer, chairperson, counsellor, editor, core member, secretary, president, VP, coordinator, head, volunteer. Quantify footfall, revenue, sponsorship (partner + amount), timeframe; events initiated; workshops; corporate talks; NGO outcome.\nextra curricular: Categories: social contribution (volunteering, crowdfunding, NGO); sports (rank, out of how many, state/national/international level, sport); public speaking (rank, participants, level, debate/JAM/extempore); creative writing/art (rank or publication, submissions, activity); cultural (rank, level, activity); miscellaneous (biking, martial arts, painting, yoga, trekking, travel, quiz)."$cfg$::jsonb)
  on conflict (key) do update set value = excluded.value, updated_at = now();
insert into public.app_config(key, value) values ('section_order', $cfg$["Professional Summary","Education","Experience","Internships","Projects","Certifications","Achievements","Leadership","Extra-curricular","Social Impact","Skills"]$cfg$::jsonb)
  on conflict (key) do update set value = excluded.value, updated_at = now();
insert into public.app_config(key, value) values ('domains', $cfg$["General","Marketing","Sales","Fo-COS/Strategy/General Management","Product Management","Supply and Operations","Finance (incl. IB/PE/VC)","HR","Data","Consulting"]$cfg$::jsonb)
  on conflict (key) do update set value = excluded.value, updated_at = now();
