":"Full time | Part time | Internship"},"start":{"type":"string","description":"Month Year, e.g. Jul 2022"},"end":{"type":"string","description":"Month Year or Present"},"responsibilities":{"type":"array","items":{"type":"string"}},"achievements":{"type":"array","items":{"type":"string"}},"tools":{"type":"array","items":{"type":"string"}}},"required":["designation","company","start","end","responsibilities","achievements"]}}},"required":["personal","education","academic_achievements","certifications","academic_projects","internships","work_experience","positions_of_responsibility","freelance_projects","research","b_plan_competitions","extra_curricular","skills","interests"]}$cfg$::jsonb)
